                    query=str((query.get("query", [""]) or [""])[0] or ""),
                    status=str((query.get("status", [""]) or [""])[0] or ""),
                    limit=int((query.get("limit", ["100"]) or ["100"])[0] or 100),
                    offset=int((query.get("offset", ["0"]) or ["0"])[0] or 0),
